#include <stdio.h>
#include <string.h>
#include <ctype.h>

typedef enum { KEYWORD, IDENTIFIER, NUMBER, OPERATOR, LPAREN, RPAREN, EOF_TOKEN } TokenType;

typedef struct { TokenType type; char value[32]; } Token;

Token next_token(char **input) {
    Token t = {0};
    while (**input == ' ') (*input)++;
    if (**input == '\0') { t.type = EOF_TOKEN; return t; }
    if (**input == '(') { t.type = LPAREN; t.value[0]='('; t.value[1]=0; (*input)++; return t; }
    if (**input == ')') { t.type = RPAREN; t.value[0]=')'; t.value[1]=0; (*input)++; return t; }
    if (strchr("+-*/", **input)) {
        t.type = OPERATOR; t.value[0]=*(*input)++; t.value[1]=0; return t;
    }
    if (isdigit(**input)) {
        t.type = NUMBER; int i=0;
        while (isdigit(**input)) t.value[i++]=*(*input)++;
        t.value[i]=0; return t;
    }
    if (isalpha(**input)) {
        int i=0;
        while (isalnum(**input)) t.value[i++]=*(*input)++;
        t.value[i]=0;
        t.type = strcmp(t.value,"let")==0||strcmp(t.value,"if")==0 ? KEYWORD : IDENTIFIER;
        return t;
    }
    return t;
}

int main() {
    char input[] = "let x = 42 + y";
    char *p = input;
    Token t;
    do {
        t = next_token(&p);
        printf("Token: type=%d value=%s\n", t.type, t.value);
    } while (t.type != EOF_TOKEN);
    return 0;
}
